-- The web app only queues jobs; running them, and every change to a job after that, is the
-- worker's, which connects as postgres. A file row is written as pending and then marked stored.
GRANT SELECT, INSERT ON public.jobs, public.files TO app_runtime;
--> statement-breakpoint
GRANT UPDATE (status, stored_at) ON public.files TO app_runtime;
--> statement-breakpoint

ALTER TABLE public.jobs ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
