--> statement-breakpoint
ALTER TABLE public.files FORCE ROW LEVEL SECURITY;
--> statement-breakpoint

-- Any member may queue work in their own company, as themselves, and only as a fresh job: not
-- already run, locked, failed or finished.
CREATE POLICY jobs_insert ON public.jobs FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND created_by = (SELECT app.current_user_id())
    AND status = 'queued'
    AND attempts = 0
    AND locked_at IS NULL AND locked_by IS NULL
    AND last_error IS NULL AND result IS NULL AND finished_at IS NULL
  );
--> statement-breakpoint
CREATE POLICY jobs_select ON public.jobs FOR SELECT TO app_runtime
  USING (tenant_id = (SELECT app.tenant_id()) AND (SELECT app.tenant_role()) IN ('owner', 'auditor'));
--> statement-breakpoint

-- Files: an owner adds them; an owner or an auditor sees them. Later steps that attach files to
-- documents widen this for the roles that work on those documents.
CREATE POLICY files_select ON public.files FOR SELECT TO app_runtime
  USING (tenant_id = (SELECT app.tenant_id()) AND (SELECT app.tenant_role()) IN ('owner', 'auditor'));
--> statement-breakpoint
CREATE POLICY files_insert ON public.files FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) = 'owner'
    AND created_by = (SELECT app.current_user_id())
    AND status = 'pending'
  );
--> statement-breakpoint
CREATE POLICY files_update ON public.files FOR UPDATE TO app_runtime
  USING (tenant_id = (SELECT app.tenant_id()) AND (SELECT app.tenant_role()) = 'owner')
  WITH CHECK (tenant_id = (SELECT app.tenant_id()) AND (SELECT app.tenant_role()) = 'owner');
--> statement-breakpoint

-- ── hand-written: the object store (Supabase Storage) ───────────────────────────────────────────
--
-- The bytes live in a private bucket. The web app reaches it as the signed-in user, never with
-- the service-role key, so Supabase Storage applies the policies below to every upload and every
-- signed link. An object's name is "<company id>/<file id>"; the first part decides who may
-- touch it.

INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES ('files', 'files', false, 4194304, ARRAY['application/pdf', 'image/png', 'image/jpeg', 'image/webp']);
--> statement-breakpoint

-- The signed-in user's role in the company whose id is given as text, or null. Storage runs as
-- the `authenticated` role with the user's id in auth.uid(); it cannot read memberships itself.
CREATE FUNCTION app.storage_role(p_tenant text) RETURNS public.member_role
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
  AS $$
    SELECT m.role
    FROM public.memberships m
    WHERE m.tenant_id::text = p_tenant
      AND m.user_id = (SELECT auth.uid())
      AND m.active
  $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.storage_role(text) FROM PUBLIC;
--> statement-breakpoint
-- `authenticated` gets this one function and nothing else in the app schema.
GRANT USAGE ON SCHEMA app TO authenticated;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.storage_role(text) TO authenticated;
--> statement-breakpoint

CREATE POLICY files_bucket_insert ON storage.objects FOR INSERT TO authenticated
  WITH CHECK (bucket_id = 'files' AND (SELECT app.storage_role((storage.foldername(name))[1])) = 'owner');
--> statement-breakpoint
CREATE POLICY files_bucket_select ON storage.objects FOR SELECT TO authenticated
  USING (bucket_id = 'files' AND (SELECT app.storage_role((storage.foldername(name))[1])) IN ('owner', 'auditor'));
